  "        one[\"agents\"] = [\"claude\", \"codex\"] if os.path.realpath(one[\"path\"]) in files else [agent]",
  "    for one in own[\"servers\"]:",
  "        one[\"agents\"] = [\"claude\", \"codex\"] if (one[\"url\"] or one[\"runs\"]) in places else [agent]",
