  "    ahead: int = 0",
  "    behind: int = 0",
  "    staged: list = field(default_factory=list)",
  "    changes: list = field(default_factory=list)",
  "    ignored: set = field(default_factory=set)       # paths from the root; a folder ends in \"/\"",
  "    error: str = None",
  "",
  "",
  "@dataclass(frozen=True)",
  "class Place:",
