  "'    parts = re.findall(r\"\\\\\\\\[*\\\\\\\\]|\\\\*\\\\*|\\\\*|[^*\\\\\\\\]+|\\\\\\\\\", words)',",
  "'    optional = parts[-1:] == [\"*\"] and len(parts) > 1 and parts[-2].endswith(\" \") \\\\',",
  "'        and sum(part in (\"*\", \"**\") for part in parts) == 1',",
