  "'def kind(name):',",
  "'    name = name.lower()',",
  "'    for glyph, icon_name, starts in BY_NAME:',",
  "'        if name.startswith(starts):',",
  "'            return glyph, icon_name',",
  "'    return BY_EXTENSION.get(os.path.splitext(name)[1][1:])',",
